Building a production-ready KSeF application involves two main layers:
1. **The Backend Engine:** Interacting with the Ministry of Finance’s REST API (authentication via token/certificate, querying metadata, fetching XMLs, parsing them).
2. **The User Interface:** Providing an intuitive dashboard for searching, sorting, and filtering downloaded invoices.

Below is a complete, working prototype built with **Python**, **FastAPI** (for KSeF integration and local storage via SQLite), and a **clean HTML5/JavaScript dashboard** (using TailwindCSS). It is configured to run against the **KSeF Test Environment**.

---

### Step 1: Project Setup

Create a new directory and install the required dependencies:

```bash
mkdir ksef-accounting-app
cd ksef-accounting-app
pip install fastapi uvicorn httpx cryptography pydantic jinja2 python-multipart
```

---

### Step 2: The Application Backend (`app.py`)

This file handles:
- Authorization session initiation with KSeF (using Challenge + RSA-encrypted token).
- Querying invoice lists for a given date range.
- Downloading and parsing XML invoices.
- Storing them locally in SQLite for rapid client-side filtering (by client, supplier, date, amount).

Save this as `app.py`:

```python
import base64
import os
import sqlite3
import xml.etree.ElementTree as ET
from datetime import datetime, timezone
from typing import List, Optional

import httpx
from cryptography.hazmat.primitives import hashes
from cryptography.hazmat.primitives.asymmetric import padding
from cryptography.hazmat.primitives.serialization import load_pem_public_key
from fastapi import FastAPI, Form, HTTPException, Request
from fastapi.responses import HTMLResponse
from fastapi.templating import Jinja2Templates

app = FastAPI(title="KSeF Accounting Client Engine")
templates = Jinja2Templates(directory="templates")

KSEF_BASE_URL = "https://ksef-test.mf.gov.pl/api"
DB_FILE = "invoices.db"


# --- DATABASE SETUP ---
def init_db():
    with sqlite3.connect(DB_FILE) as conn:
        cursor = conn.cursor()
        cursor.execute(
            """
            CREATE TABLE IF NOT EXISTS invoices (
                ksef_reference_number TEXT PRIMARY KEY,
                client_nip TEXT,
                supplier_nip TEXT,
                supplier_name TEXT,
                invoice_number TEXT,
                issue_date TEXT,
                net_amount REAL,
                gross_amount REAL,
                currency TEXT,
                xml_content TEXT
            )
        """
        )
        conn.commit()


init_db()


# --- KSEF CRYPTO HELPERS ---
def encrypt_token(token: str, timestamp_ms: int, public_key_pem: bytes) -> str:
    """Encrypts Token|Timestamp using KSeF RSA Public Key"""
    payload = f"{token}|{timestamp_ms}".encode("utf-8")
    public_key = load_pem_public_key(public_key_pem)
    encrypted = public_key.encrypt(
        payload,
        padding.OAEP(
            mgf=padding.MGF1(algorithm=hashes.SHA256()),
            algorithm=hashes.SHA256(),
            label=None,
        ),
    )
    return base64.b64encode(encrypted).decode("utf-8")


# --- KSEF SERVICE ---
class KSeFClient:

    def __init__(self, nip: str, token: str):
        self.nip = nip
        self.token = token
        self.session_token = None

    async def authenticate(self, client: httpx.AsyncClient):
        # 1. Authorisation Challenge
        challenge_resp = await client.post(
            f"{KSEF_BASE_URL}/online/Session/AuthorisationChallenge",
            json={"contextIdentifier": {"type": "onip", "identifier": self.nip}},
        )
        if challenge_resp.status_code != 200:
            raise HTTPException(
                status_code=400,
                detail=f"KSeF Challenge Failed: {challenge_resp.text}",
            )

        challenge_data = challenge_resp.json()
        challenge = challenge_data["challenge"]
        timestamp = challenge_data["timestamp"]

        # Parse timestamp to ms
        dt = datetime.fromisoformat(timestamp.replace("Z", "+00:00"))
        timestamp_ms = int(dt.timestamp() * 1000)

        # 2. Get Public Key
        pk_resp = await client.get(
            f"{KSEF_BASE_URL}/online/Session/PublicKeyCertificate"
        )
        pub_key_pem = pk_resp.text.encode("utf-8")

        # 3. Encrypt Authentication Token
        encrypted_token = encrypt_token(
            f"{self.token}|{challenge}", timestamp_ms, pub_key_pem
        )

        # 4. Init Token Session
        init_payload = {
            "context": {
                "challenge": challenge,
                "identifier": {"type": "onip", "identifier": self.nip},
                "documentType": {
                    "service": "KSeF",
                    "type": "Online",
                    "schema": "FA (2)",
                },
                "token": encrypted_token,
            }
        }
        init_resp = await client.post(
            f"{KSEF_BASE_URL}/online/Session/InitToken", json=init_payload
        )
        if init_resp.status_code != 201:
            raise HTTPException(
                status_code=400,
                detail=f"KSeF Auth Failed: {init_resp.text}",
            )

        self.session_token = init_resp.json()["sessionToken"]["token"]

    async def sync_purchase_invoices(
        self, client: httpx.AsyncClient, date_from: str, date_to: str
    ):
        headers = {"SessionToken": self.session_token}
        query_payload = {
            "queryCriteria": {
                "type": "detail",
                "invoicingDateFrom": f"{date_from}T00:00:00Z",
                "invoicingDateTo": f"{date_to}T23:59:59Z",
                "subjectType": "subject2",  # subject2 = Buyer (Fetch Purchases)
            }
        }

        # Query metadata
        resp = await client.post(
            f"{KSEF_BASE_URL}/online/Invoice/Sync/QueryCriteria",
            json=query_payload,
            headers=headers,
        )
        if resp.status_code != 200:
            raise HTTPException(
                status_code=400,
                detail=f"Failed to query invoices: {resp.text}",
            )

        invoices_meta = (
            resp.json().get("invoiceHeaderList", [])
            if resp.json().get("invoiceHeaderList")
            else []
        )

        with sqlite3.connect(DB_FILE) as conn:
            cursor = conn.cursor()
            for meta in invoices_meta:
                ksef_ref = meta["ksefReferenceNumber"]

                # Download complete XML invoice
                xml_resp = await client.get(
                    f"{KSEF_BASE_URL}/online/Invoice/Get/{ksef_ref}",
                    headers=headers,
                )
                if xml_resp.status_code == 200:
                    xml_text = xml_resp.text
                    parsed = self._parse_fa2_xml(xml_text)

                    cursor.execute(
                        """
                        INSERT OR REPLACE INTO invoices 
                        (ksef_reference_number, client_nip, supplier_nip, supplier_name, invoice_number, issue_date, net_amount, gross_amount, currency, xml_content)
                        VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                    """,
                        (
                            ksef_ref,
                            self.nip,
                            parsed["supplier_nip"],
                            parsed["supplier_name"],
                            parsed["invoice_number"],
                            parsed["issue_date"],
                            parsed["net_amount"],
                            parsed["gross_amount"],
                            parsed["currency"],
                            xml_text,
                        ),
                    )
            conn.commit()

    def _parse_fa2_xml(self, xml_content: str) -> dict:
        """Parses standard FA(2) Schema XML"""
        root = ET.fromstring(xml_content)
        # Handle default namespace wildcard
        ns = {"ns": root.tag.split("}")[0].strip("{")} if "}" in root.tag else {}

        def find(path):
            return (
                root.find(path, ns).text
                if root.find(path, ns) is not None
                else ""
            )

        return {
            "supplier_nip": find(".//ns:Podmiot1/ns:DaneIdentyfikujace/ns:NIP"),
            "supplier_name": find(
                ".//ns:Podmiot1/ns:DaneIdentyfikujace/ns:Nazwa"
            ),
            "invoice_number": find(".//ns:Fa/ns:P_2"),
            "issue_date": find(".//ns:Fa/ns:P_1"),
            "net_amount": float(find(".//ns:Fa/ns:P_13_1") or 0.0),
            "gross_amount": float(find(".//ns:Fa/ns:P_15") or 0.0),
            "currency": find(".//ns:Fa/ns:KodWaluty") or "PLN",
        }


# --- ROUTES ---


@app.get("/", response_class=HTMLResponse)
def index(request: Request):
    return templates.TemplateResponse("index.html", {"request": request})


@app.post("/api/sync")
async def sync_ksef(
    nip: str = Form(...),
    token: str = Form(...),
    date_from: str = Form(...),
    date_to: str = Form(...),
):
    ksef = KSeFClient(nip=nip, token=token)
    async with httpx.AsyncClient(timeout=30.0) as client:
        await ksef.authenticate(client)
        await ksef.sync_purchase_invoices(client, date_from, date_to)
    return {"status": "success", "message": "Invoices synced successfully."}


@app.get("/api/invoices")
def get_invoices(
    client_nip: Optional[str] = None,
    supplier: Optional[str] = None,
    date_from: Optional[str] = None,
    date_to: Optional[str] = None,
    min_amount: Optional[float] = None,
    max_amount: Optional[float] = None,
):
    query = "SELECT ksef_reference_number, client_nip, supplier_nip, supplier_name, invoice_number, issue_date, net_amount, gross_amount, currency FROM invoices WHERE 1=1"
    params = []

    if client_nip:
        query += " AND client_nip = ?"
        params.append(client_nip)
    if supplier:
        query += " AND (supplier_name LIKE ? OR supplier_nip LIKE ?)"
        params.extend([f"%{supplier}%", f"%{supplier}%"])
    if date_from:
        query += " AND issue_date >= ?"
        params.append(date_from)
    if date_to:
        query += " AND issue_date <= ?"
        params.append(date_to)
    if min_amount is not None:
        query += " AND gross_amount >= ?"
        params.append(min_amount)
    if max_amount is not None:
        query += " AND gross_amount <= ?"
        params.append(max_amount)

    query += " ORDER BY issue_date DESC"

    with sqlite3.connect(DB_FILE) as conn:
        conn.row_factory = sqlite3.Row
        cursor = conn.cursor()
        rows = cursor.execute(query, params).fetchall()
        return [dict(row) for row in rows]
```

