            e.preventDefault();
            const btn = document.getElementById('syncBtn');
            const status = document.getElementById('syncStatus');
            btn.disabled = true;
            btn.innerText = 'Syncing...';
            status.className = 'mt-3 text-sm text-blue-600 block';
            status.innerText = 'Connecting to KSeF...';

            const formData = new FormData();
            formData.append('nip', document.getElementById('syncNip').value);
            formData.append('token', document.getElementById('syncToken').value);
            formData.append('date_from', document.getElementById('syncFrom').value);
            formData.append('date_to', document.getElementById('syncTo').value);

            try {
                const res = await fetch('/api/sync', { method: 'POST', body: formData });
                const data = await res.json();
                if (res.ok) {
                    status.className = 'mt-3 text-sm text-green-600 block';
                    status.innerText = data.message;
                    loadInvoices();
                } else {
                    throw new Error(data.detail || 'Sync failed');
                }
            } catch (err) {
                status.className = 'mt-3 text-sm text-red-600 block';
                status.innerText = err.message;
            } finally {
                btn.disabled = false;
                btn.innerText = 'Fetch Invoices';
            }
        });

        async function loadInvoices() {
            const params = new URLSearchParams();
            if (document.getElementById('filterClientNip').value) params.append('client_nip', document.getElementById('filterClientNip').value);
            if (document.getElementById('filterSupplier').value) params.append('supplier', document.getElementById('filterSupplier').value);
            if (document.getElementById('filterDateFrom').value) params.append('date_from', document.getElementById('filterDateFrom').value);
            if (document.getElementById('filterDateTo').value) params.append('date_to', document.getElementById('filterDateTo').value);
            if (document.getElementById('filterMinAmount').value) params.append('min_amount', document.getElementById('filterMinAmount').value);
            if (document.getElementById('filterMaxAmount').value) params.append('max_amount', document.getElementById('filterMaxAmount').value);

            const res = await fetch('/api/invoices?' + params.toString());
            const data = await res.json();

            const tbody = document.getElementById('invoiceTableBody');
            tbody.innerHTML = '';
            if (data.length === 0) {
                tbody.innerHTML = '<tr><td colspan="8" class="p-4 text-center text-slate-400">No invoices found.</td></tr>';
                return;
            }

            data.forEach(inv => {
                const tr = document.createElement('tr');
                tr.className = 'hover:bg-slate-50 transition';
                tr.innerHTML = `
                    <td class="p-3 font-medium text-slate-700">${inv.issue_date}</td>
                    <td class="p-3 text-slate-600">${inv.client_nip}</td>
                    <td class="p-3 font-semibold text-slate-800">${inv.supplier_name || 'N/A'}</td>
                    <td class="p-3 text-slate-600">${inv.supplier_nip || 'N/A'}</td>
                    <td class="p-3 text-slate-600">${inv.invoice_number}</td>
                    <td class="p-3 text-right">${inv.net_amount.toFixed(2)} ${inv.currency}</td>
                    <td class="p-3 text-right font-semibold text-slate-800">${inv.gross_amount.toFixed(2)} ${inv.currency}</td>
                    <td class="p-3 text-xs text-slate-400 font-mono" title="${inv.ksef_reference_number}">${inv.ksef_reference_number.substring(0, 15)}...</td>
                `;
                tbody.appendChild(tr);
            });
        }

        function resetFilters() {
            document.querySelectorAll('section input').forEach(input => input.value = '');
            loadInvoices();
        }

        // Initialize table
        loadInvoices();
    </script>
</body>
</html>
```

