        with sqlite3.connect(DB_FILE) as conn:
            cursor = conn.cursor()
            for meta in invoices_meta:
                ksef_ref = meta["ksefReferenceNumber"]

                # Download complete XML invoice
                xml_resp = await client.get(
                    f"{KSEF_BASE_URL}/online/Invoice/Get/{ksef_ref}",
                    headers=headers,
                )
                if xml_resp.status_code == 200:
                    xml_text = xml_resp.text
                    parsed = self._parse_fa2_xml(xml_text)

                    cursor.execute(
                        """
                        INSERT OR REPLACE INTO invoices 
                        (ksef_reference_number, client_nip, supplier_nip, supplier_name, invoice_number, issue_date, net_amount, gross_amount, currency, xml_content)
                        VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                    """,
                        (
                            ksef_ref,
                            self.nip,
                            parsed["supplier_nip"],
                            parsed["supplier_name"],
                            parsed["invoice_number"],
                            parsed["issue_date"],
                            parsed["net_amount"],
                            parsed["gross_amount"],
                            parsed["currency"],
                            xml_text,
                        ),
                    )
            conn.commit()

    def _parse_fa2_xml(self, xml_content: str) -> dict:
        """Parses standard FA(2) Schema XML"""
        root = ET.fromstring(xml_content)
        # Handle default namespace wildcard
        ns = {"ns": root.tag.split("}")[0].strip("{")} if "}" in root.tag else {}

        def find(path):
            return (
                root.find(path, ns).text
                if root.find(path, ns) is not None
                else ""
            )

        return {
            "supplier_nip": find(".//ns:Podmiot1/ns:DaneIdentyfikujace/ns:NIP"),
            "supplier_name": find(
                ".//ns:Podmiot1/ns:DaneIdentyfikujace/ns:Nazwa"
            ),
            "invoice_number": find(".//ns:Fa/ns:P_2"),
            "issue_date": find(".//ns:Fa/ns:P_1"),
            "net_amount": float(find(".//ns:Fa/ns:P_13_1") or 0.0),
            "gross_amount": float(find(".//ns:Fa/ns:P_15") or 0.0),
            "currency": find(".//ns:Fa/ns:KodWaluty") or "PLN",
        }


