@app.post("/api/sync")
async def sync_ksef(
    nip: str = Form(...),
    token: str = Form(...),
    date_from: str = Form(...),
    date_to: str = Form(...),
):
    ksef = KSeFClient(nip=nip, token=token)
    async with httpx.AsyncClient(timeout=30.0) as client:
        await ksef.authenticate(client)
        await ksef.sync_purchase_invoices(client, date_from, date_to)
    return {"status": "success", "message": "Invoices synced successfully."}


@app.get("/api/invoices")
def get_invoices(
    client_nip: Optional[str] = None,
    supplier: Optional[str] = None,
    date_from: Optional[str] = None,
    date_to: Optional[str] = None,
    min_amount: Optional[float] = None,
    max_amount: Optional[float] = None,
):
    query = "SELECT ksef_reference_number, client_nip, supplier_nip, supplier_name, invoice_number, issue_date, net_amount, gross_amount, currency FROM invoices WHERE 1=1"
    params = []

    if client_nip:
        query += " AND client_nip = ?"
        params.append(client_nip)
    if supplier:
        query += " AND (supplier_name LIKE ? OR supplier_nip LIKE ?)"
        params.extend([f"%{supplier}%", f"%{supplier}%"])
    if date_from:
        query += " AND issue_date >= ?"
        params.append(date_from)
    if date_to:
        query += " AND issue_date <= ?"
        params.append(date_to)
    if min_amount is not None:
        query += " AND gross_amount >= ?"
        params.append(min_amount)
    if max_amount is not None:
        query += " AND gross_amount <= ?"
        params.append(max_amount)

    query += " ORDER BY issue_date DESC"

    with sqlite3.connect(DB_FILE) as conn:
        conn.row_factory = sqlite3.Row
        cursor = conn.cursor()
        rows = cursor.execute(query, params).fetchall()
        return [dict(row) for row in rows]
